contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary amount to forward to c.go
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // Observe owner and balances before the call
        address ownerBefore = c.owner();
        uint balThisBefore = address(this).balance;
        uint balCBefore = address(c).balance;

        // Call c.go forwarding `amount` wei
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        address ownerAfter = c.owner();
        uint balThisAfter = address(this).balance;
        uint balCAfter = address(c).balance;

        // General rule: call does not change owner, and if the call did not revert,
        // then the test contract's balance is >= before (it should not have lost net ether),
        // and C's balance is <= before. We write this as a single assert combining them.
        assert(ownerBefore == ownerAfter && (reverted || (balThisAfter >= balThisBefore && balCAfter <= balCBefore)));
    }

    // Allow receiving ether in fallback/receive to simulate owner transfer target behavior
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address origOwner;

    constructor(C _c) { c = _c; origOwner = c.owner(); }

    // run tries calling c.go with arbitrary amount; check owner unchanged and that
    // this contract's balance did not increase by more than the amount forwarded.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeBalance = address(this).balance;
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner after the call
        address afterOwner = c.owner();
        uint afterBalance = address(this).balance;

        // General rule: if call succeeded then owner unchanged and this contract's balance
        // increased by at most amount (cannot receive more than was sent to c).
        assert(reverted || (afterOwner == origOwner && afterBalance <= beforeBalance + amount));
    }

    receive() external payable {}
}

