        // read pre-call observable values
        address preOwner = c.owner();
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        bool reverted;
        // make the state-changing call as specified
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

